import os
from pathlib import Path
import duckdb
d = Path(os.environ['MIMIC_DERIVED'])
temp = Path(os.environ['REPRO_TEMP'])
cohort = d / 'vasopressor_liberation_primary_cohort_stage3.parquet'
vitals = d / 'preliberation_vitals_6h_clean_stage5.parquet'
labs = d / 'preliberation_labs_6h_clean_stage5.parquet'
doses = d / 'vasopressor_inputevents_nee_clean_stage6.parquet'
output = d / 'vasopressor_liberation_features_stage7.parquet'
if output.exists():
    raise SystemExit(f'输出已存在，未覆盖：{output}')

def sql_path(p):
    return str(p).replace('\\', '/').replace("'", "''")
con = duckdb.connect()
con.execute('SET threads = 1')
con.execute("SET memory_limit = '8GB'")
con.execute(f"SET temp_directory = '{sql_path(temp)}'")
con.execute('SET preserve_insertion_order = true')
print('构建生命体征动态特征……')
con.execute(f"\nCREATE TEMP TABLE vital_features AS\nWITH map_ranked AS (\n    SELECT *,\n        row_number() OVER (\n            PARTITION BY stay_id, charttime\n            ORDER BY CASE\n                WHEN variable = 'map_arterial' THEN 0 ELSE 1\n            END, source_row_number\n        ) AS source_rank\n    FROM read_parquet('{sql_path(vitals)}')\n    WHERE variable IN ('map_arterial', 'map_noninvasive')\n),\nmap_values AS (\n    SELECT *\n    FROM map_ranked\n    WHERE source_rank = 1\n),\nmap_agg AS (\n    SELECT\n        stay_id,\n        count(*) AS map_count_6h,\n        arg_min(valuenum, struct_pack(minutes := minutes_before_stop, source_row := source_row_number)) AS map_last,\n        min(minutes_before_stop) AS map_minutes_since_last,\n        avg(valuenum) FILTER (\n            WHERE minutes_before_stop <= 60\n        ) AS map_mean_1h,\n        min(valuenum) FILTER (\n            WHERE minutes_before_stop <= 60\n        ) AS map_min_1h,\n        stddev_samp(valuenum) FILTER (\n            WHERE minutes_before_stop <= 60\n        ) AS map_sd_1h,\n        avg(valuenum) AS map_mean_6h,\n        min(valuenum) AS map_min_6h,\n        stddev_samp(valuenum) AS map_sd_6h,\n        regr_slope(\n            valuenum, -minutes_before_stop / 60.0\n        ) AS map_slope_toward_stop_6h,\n        100.0 * avg(\n            CASE WHEN valuenum < 65 THEN 1.0 ELSE 0.0 END\n        ) FILTER (\n            WHERE minutes_before_stop <= 60\n        ) AS map_below65_pct_1h,\n        100.0 * avg(\n            CASE WHEN valuenum < 65 THEN 1.0 ELSE 0.0 END\n        ) AS map_below65_pct_6h,\n        100.0 * avg(\n            CASE WHEN variable = 'map_arterial' THEN 1.0 ELSE 0.0 END\n        ) AS map_arterial_pct_6h\n    FROM map_values\n    GROUP BY stay_id\n),\nhr_agg AS (\n    SELECT\n        stay_id,\n        count(*) AS hr_count_6h,\n        arg_min(valuenum, struct_pack(minutes := minutes_before_stop, source_row := source_row_number)) AS heart_rate_last,\n        min(minutes_before_stop) AS hr_minutes_since_last,\n        avg(valuenum) FILTER (\n            WHERE minutes_before_stop <= 60\n        ) AS heart_rate_mean_1h,\n        stddev_samp(valuenum) FILTER (\n            WHERE minutes_before_stop <= 60\n        ) AS heart_rate_sd_1h,\n        avg(valuenum) AS heart_rate_mean_6h,\n        stddev_samp(valuenum) AS heart_rate_sd_6h,\n        regr_slope(\n            valuenum, -minutes_before_stop / 60.0\n        ) AS heart_rate_slope_toward_stop_6h\n    FROM read_parquet('{sql_path(vitals)}')\n    WHERE variable = 'heart_rate'\n    GROUP BY stay_id\n),\nother_agg AS (\n    SELECT\n        stay_id,\n        arg_min(valuenum, struct_pack(minutes := minutes_before_stop, source_row := source_row_number))\n            FILTER (WHERE variable = 'spo2') AS spo2_last,\n        avg(valuenum)\n            FILTER (WHERE variable = 'spo2') AS spo2_mean_6h,\n        arg_min(valuenum, struct_pack(minutes := minutes_before_stop, source_row := source_row_number))\n            FILTER (WHERE variable = 'respiratory_rate')\n            AS respiratory_rate_last,\n        avg(valuenum)\n            FILTER (WHERE variable = 'respiratory_rate')\n            AS respiratory_rate_mean_6h,\n        arg_min(valuenum, struct_pack(minutes := minutes_before_stop, source_row := source_row_number))\n            FILTER (WHERE variable = 'temperature_c')\n            AS temperature_c_last\n    FROM read_parquet('{sql_path(vitals)}')\n    GROUP BY stay_id\n)\nSELECT\n    c.stay_id,\n    m.map_count_6h,\n    m.map_last,\n    m.map_minutes_since_last,\n    m.map_mean_1h,\n    m.map_min_1h,\n    m.map_sd_1h,\n    m.map_mean_6h,\n    m.map_min_6h,\n    m.map_sd_6h,\n    m.map_slope_toward_stop_6h,\n    m.map_below65_pct_1h,\n    m.map_below65_pct_6h,\n    m.map_arterial_pct_6h,\n    h.hr_count_6h,\n    h.heart_rate_last,\n    h.hr_minutes_since_last,\n    h.heart_rate_mean_1h,\n    h.heart_rate_sd_1h,\n    h.heart_rate_mean_6h,\n    h.heart_rate_sd_6h,\n    h.heart_rate_slope_toward_stop_6h,\n    o.spo2_last,\n    o.spo2_mean_6h,\n    o.respiratory_rate_last,\n    o.respiratory_rate_mean_6h,\n    o.temperature_c_last\nFROM read_parquet('{sql_path(cohort)}') AS c\nLEFT JOIN map_agg AS m USING (stay_id)\nLEFT JOIN hr_agg AS h USING (stay_id)\nLEFT JOIN other_agg AS o USING (stay_id)\n")
print('构建检验特征……')
con.execute(f"\nCREATE TEMP TABLE lab_features AS\nSELECT\n    c.stay_id,\n    arg_min(l.valuenum, struct_pack(minutes := l.minutes_before_stop, source_row := l.source_row_number))\n        FILTER (WHERE l.variable = 'lactate') AS lactate_last,\n    min(l.minutes_before_stop)\n        FILTER (WHERE l.variable = 'lactate') AS lactate_minutes_since,\n    arg_min(l.valuenum, struct_pack(minutes := l.minutes_before_stop, source_row := l.source_row_number))\n        FILTER (WHERE l.variable = 'creatinine') AS creatinine_last,\n    min(l.minutes_before_stop)\n        FILTER (WHERE l.variable = 'creatinine') AS creatinine_minutes_since,\n    arg_min(l.valuenum, struct_pack(minutes := l.minutes_before_stop, source_row := l.source_row_number))\n        FILTER (WHERE l.variable = 'bicarbonate') AS bicarbonate_last,\n    min(l.minutes_before_stop)\n        FILTER (WHERE l.variable = 'bicarbonate') AS bicarbonate_minutes_since,\n    arg_min(l.valuenum, struct_pack(minutes := l.minutes_before_stop, source_row := l.source_row_number))\n        FILTER (WHERE l.variable = 'ph') AS ph_last,\n    min(l.minutes_before_stop)\n        FILTER (WHERE l.variable = 'ph') AS ph_minutes_since,\n    arg_min(l.valuenum, struct_pack(minutes := l.minutes_before_stop, source_row := l.source_row_number))\n        FILTER (WHERE l.variable = 'base_excess') AS base_excess_last,\n    arg_min(l.valuenum, struct_pack(minutes := l.minutes_before_stop, source_row := l.source_row_number))\n        FILTER (WHERE l.variable = 'hemoglobin') AS hemoglobin_last,\n    arg_min(l.valuenum, struct_pack(minutes := l.minutes_before_stop, source_row := l.source_row_number))\n        FILTER (WHERE l.variable = 'platelets') AS platelets_last,\n    arg_min(l.valuenum, struct_pack(minutes := l.minutes_before_stop, source_row := l.source_row_number))\n        FILTER (WHERE l.variable = 'wbc') AS wbc_last,\n    arg_min(l.valuenum, struct_pack(minutes := l.minutes_before_stop, source_row := l.source_row_number))\n        FILTER (WHERE l.variable = 'bilirubin_total')\n        AS bilirubin_total_last,\n    arg_min(l.valuenum, struct_pack(minutes := l.minutes_before_stop, source_row := l.source_row_number))\n        FILTER (WHERE l.variable = 'albumin') AS albumin_last\nFROM read_parquet('{sql_path(cohort)}') AS c\nLEFT JOIN read_parquet('{sql_path(labs)}') AS l USING (stay_id)\nGROUP BY c.stay_id\n")
print('构建15分钟NEE轨迹……')
con.execute(f"\nCREATE TEMP TABLE dose_features AS\nWITH grid AS (\n    SELECT\n        c.stay_id,\n        c.episode_end,\n        r.offset_min,\n        c.episode_end\n          - r.offset_min * INTERVAL '1 minute' AS grid_time\n    FROM read_parquet('{sql_path(cohort)}') AS c\n    CROSS JOIN range(5, 361, 15) AS r(offset_min)\n),\ndrug_grid AS (\n    SELECT\n        g.stay_id,\n        g.offset_min,\n        e.drug,\n        max(e.norepinephrine_equivalent) AS drug_nee\n    FROM grid AS g\n    INNER JOIN read_parquet('{sql_path(doses)}') AS e\n        ON g.stay_id = e.stay_id\n       AND g.grid_time >= e.starttime\n       AND g.grid_time < e.endtime\n    GROUP BY g.stay_id, g.offset_min, e.drug\n),\ntotal_grid AS (\n    SELECT\n        g.stay_id,\n        g.offset_min,\n        coalesce(sum(dg.drug_nee), 0) AS total_nee,\n        count(dg.drug) AS active_agents\n    FROM grid AS g\n    LEFT JOIN drug_grid AS dg\n        ON g.stay_id = dg.stay_id\n       AND g.offset_min = dg.offset_min\n    GROUP BY g.stay_id, g.offset_min\n)\nSELECT\n    stay_id,\n    arg_min(total_nee, offset_min) AS nee_last_5min,\n    avg(total_nee) FILTER (\n        WHERE offset_min <= 60\n    ) AS nee_mean_1h,\n    max(total_nee) FILTER (\n        WHERE offset_min <= 60\n    ) AS nee_max_1h,\n    avg(total_nee) AS nee_mean_6h,\n    max(total_nee) AS nee_max_6h,\n    regr_slope(\n        total_nee, -offset_min / 60.0\n    ) AS nee_slope_toward_stop_6h,\n    arg_min(active_agents, offset_min) AS active_agents_last_5min,\n    max(active_agents) AS maximum_active_agents_6h,\n    100.0 * avg(\n        CASE WHEN total_nee = 0 THEN 1.0 ELSE 0.0 END\n    ) AS zero_nee_grid_pct_6h\nFROM total_grid\nGROUP BY stay_id\n")
print('合并特征矩阵……')
con.execute(f"\nCOPY (\n    SELECT\n        c.*,\n        v.* EXCLUDE (stay_id),\n        l.* EXCLUDE (stay_id),\n        x.* EXCLUDE (stay_id),\n        v.heart_rate_last / nullif(v.map_last, 0)\n            AS modified_shock_index_last,\n        x.nee_last_5min / nullif(x.nee_max_6h, 0)\n            AS nee_last_to_max_ratio\n    FROM read_parquet('{sql_path(cohort)}') AS c\n    LEFT JOIN vital_features AS v USING (stay_id)\n    LEFT JOIN lab_features AS l USING (stay_id)\n    LEFT JOIN dose_features AS x USING (stay_id)\n)\nTO '{sql_path(output)}'\n(FORMAT PARQUET, COMPRESSION ZSTD)\n")
qa = con.execute(f"\nSELECT\n    count(*) AS rows,\n    count(DISTINCT stay_id) AS unique_stays,\n    sum(failure_24h) AS failures,\n    round(100.0 * avg(failure_24h), 2) AS failure_pct,\n    count(map_last) AS map_available,\n    count(heart_rate_last) AS hr_available,\n    count(nee_last_5min) AS nee_available,\n    count(lactate_last) AS lactate_available\nFROM read_parquet('{sql_path(output)}')\n").fetchdf()
comparison = con.execute(f"\nSELECT\n    failure_24h,\n    count(*) AS stays,\n    round(median(map_last), 2) AS median_map_last,\n    round(median(map_below65_pct_1h), 2) AS median_map_below65_pct_1h,\n    round(median(heart_rate_last), 2) AS median_hr_last,\n    round(median(modified_shock_index_last), 3) AS median_msi,\n    round(median(nee_last_5min), 4) AS median_nee_last,\n    round(median(nee_slope_toward_stop_6h), 4) AS median_nee_slope,\n    round(median(lactate_last), 2) AS median_lactate\nFROM read_parquet('{sql_path(output)}')\nGROUP BY failure_24h\nORDER BY failure_24h\n").fetchdf()
print('STAGE 7 FEATURE MATRIX COMPLETED')
print('\nQA')
print(qa.to_string(index=False))
print('\nSUCCESS VS FAILURE SANITY CHECK')
print(comparison.to_string(index=False))
print(f'\nOutput: {output}')
con.close()
